// cell(criterion, footprint id, value, label, [direction, delta, extra?] | null, 'earlier value', 'note', overrides?)
// builds the full cell: { value, unit, vintage, label, source, sourceUrl, sourceId, method, footprint, retrieved,
// [scenario], trajectory, audit }. A null trajectory means the dataset has no honest regional trend (not_available).
function cell(crit, footprint, value, label, traj, prior, note, over) {
  const s = SRC[crit];
  const c = { value, unit: s.unit, vintage: s.vintage, label, source: s.source, sourceUrl: s.sourceUrl, sourceId: s.sourceId, method: s.method, footprint: s.footprint || footprint, retrieved: RETRIEVED };
  if (s.scenario) c.scenario = s.scenario;
  if (traj) {
    const t = s.traj;
    c.trajectory = { status: t.status, direction: traj[0], delta: traj[1], unit: t.unit, basis: traj[2] ? `${t.basis}. ${traj[2]}` : t.basis, source: t.source, sourceUrl: t.sourceUrl, vintage: t.vintage };
  } else c.trajectory = { status: 'not_available', direction: null, basis: s.noTraj };
  c.audit = `${prior} -> ${value} ${s.unit}: ${s.why}${note ? `; ${note}` : ''}`;
  return over ? { ...c, ...over } : c;
}
// One region's block: { criterion: [value, label, trajectory, prior, note, overrides?] } or a literal null-cell object.
const block = (footprint, cells) => Object.fromEntries(Object.entries(cells).map(([crit, a]) => [crit, Array.isArray(a) ? cell(crit, footprint, ...a) : a]));

